def findMostFrequentVowelAndConsonant(s):
    # Initialize array of 26 to count each letter's frequency
    freq = [0] * 26
    vowels = {'a', 'e', 'i', 'o', 'u'}

    # Count frequency of each letter
    for ch in s:
        idx = ord(ch) - ord('a')
        freq[idx] += 1

    max_vowel = 0
    max_consonant = 0

    for i in range(26):
        ch = chr(ord('a') + i)
        if freq[i] == 0:
            continue
        if ch in vowels:
            if freq[i] > max_vowel:
                max_vowel = freq[i]
        else:
            if freq[i] > max_consonant:
                max_consonant = freq[i]

    return max_vowel + max_consonant
